export class CustodyListPage {
  private http = inject(HttpClient);
  private toast = inject(ToastService);
  private auth = inject(AuthService);
  protected router = inject(Router);
  private api = inject(ApiClient);
  private translate = inject(TranslateService);

  constructor() {
    void firstValueFrom(this.api.loadLookups()).then((l) => {
      this.agentOptions.set(l.agents);
    });
  }

  readonly tableKey = 'list.component';

  readonly columns = [
    { field: 'agent', searchField: 'agent', header: 'custody.list.col_agent', sortable: true },
    { field: 'amount', header: 'custody.list.col_amount', sortable: true },
    { field: 'transferred_in', header: 'custody.list.col_transferred_in', sortable: true },
    { field: 'spent', header: 'custody.list.col_spent', sortable: true },
    { field: 'remaining', header: 'custody.list.col_remaining', sortable: true },
    { field: 'spent_percent', header: 'custody.list.col_spent_percent', sortable: true },
    { field: 'status', header: 'custody.list.col_status', sortable: true },
    { field: 'actions', header: 'common.actions', sortable: false },
  ];

  /** status choices — the exact values CustodyController@index filters on */
  readonly statusTabs = [
    { value: 'all' },
    { value: 'pending' },
    { value: 'accepted' },
    { value: 'active' },
    { value: 'partially_returned' },
    { value: 'closed' },
    { value: 'cancelled' },
    { value: 'rejected' },
  ];

  /** status select options with translated labels (Arabic-only UI) */
  readonly statusOptions = computed(() =>
    this.statusTabs.map((t) => ({
      value: t.value,
      label:
        t.value === 'all'
          ? this.translate.instant('custody.list.tab_all')
          : this.translate.instant(`enums.custody_status.${t.value}`),
    })),
  );

  /** agent filter choices from the shared lookups */
  readonly agentOptions = signal<{ id: number; name: string }[]>([]);

  /** Blade actions.blade.php shows the return modal for the agent's own accepted custody */
  readonly openStates = ['accepted', 'active', 'partially_returned'];

  params = signal<CustodyListParams>({ page: 1, per_page: 25, q: '', status: 'all' });

  data = resource<ListResponse<Row>, unknown>({
    loader: () =>
      firstValueFrom(this.http.get<ListResponse<Row>>('/custodies', { params: cleanParams(this.params()) })),
  });

  canCreate = computed(() => this.auth.can('may_create_custody'));
  canApprove = computed(() => this.auth.can('may_approve_custody'));
  isAgent = computed(() => this.auth.can('is_agent'));
  /** Blade: accountants and managers get the office variants of the create buttons */
  isOffice = computed(() => this.auth.can('is_accountant') || this.auth.can('is_manager'));

  /** creation variants in the split button (T6-10): for me / as agent / transfer */
  createMenuItems = computed<MenuItem[]>(() => [
    { label: this.translate.instant('custody.list.personal_request'), command: () => void this.router.navigateByUrl('/custodies/new?for=self') },
    { label: this.translate.instant('custody.list.agent_request'), command: () => void this.router.navigateByUrl('/custodies/new') },
    { label: this.translate.instant('custody.list.transfer_custody'), command: () => void this.router.navigateByUrl('/transfers/new') },
  ]);

  // ── T6-30: table-driven filter definitions (agent, status) ────────────
  readonly filterDefs = computed<TableFilterDef[]>(() => [
    {
      key: 'status', label: 'common.status', type: 'select', order: 1,
      options: this.statusOptions().filter((o) => o.value !== 'all'),
    },
    {
      key: 'agent_id', label: 'custody.list.col_agent', type: 'select', order: 2,
      options: this.agentOptions().map((a) => ({ value: a.id, label: a.name })),
    },
  ]);

  /** the table emits the full query — filters reach the server (T6-30) */
  onQuery(query: TableQuery): void {
    const f = query.filters;
    this.params.update((p) => ({
      ...p,
      page: query.page,
      per_page: query.perPage,
      sort: query.sort !== '' ? query.sort : p.sort,
      q: query.q,
      status: (f.status as string) ?? 'all',
      agent_id: (f.agent_id as number) ?? null,
    }));
    this.data.reload();
  }

  active = signal<Row | null>(null);
  sending = signal(false);
  actionError = signal<HttpErrorResponse | null>(null);

  private reason = viewChild.required(ReasonDialogComponent);

  summaryValue(key: string): string {
    const value = this.data.value()?.meta.summary?.[key];
    return typeof value === 'number' || typeof value === 'string' ? String(value) : '0';
  }

  setParam(key: string, value: string | number | null): void {
    this.params.update((p) => ({ ...p, [key]: value, page: 1 }));
    this.data.reload();
  }

  onSearch(term: string): void { this.setParam('q', term); }

  /** row actions per status/role (actions.blade.php) — view/accept/return link to the detail, reject opens the reason dialog */
  actionsFor(row: Row): RowActionItem[] {
    return [
      { icon: 'eye', label: 'common.view', route: ['/custodies', row.id] },
      {
        icon: 'check',
        label: 'custody.detail.accept',
        route: ['/custodies', row.id],
        visible: row.status === 'pending' && this.canApprove(),
      },
      {
        icon: 'x',
        label: 'custody.list.reject_action',
        severity: 'danger',
        handler: () => { this.openReject(row); },
        visible: row.status === 'pending' && this.canApprove(),
      },
      {
        icon: 'cash',
        label: 'custody.detail.return',
        route: ['/custodies', row.id],
        visible: this.isAgent() && this.openStates.includes(row.status),
      },
    ];
  }

  openReject(row: Row): void {
    this.active.set(row);
    this.actionError.set(null);
    this.reason().open();
  }

  submitReject(reason: string): void {
    const row = this.active();
    if (row === null) {
      return;
    }
    this.sending.set(true);
    this.actionError.set(null);
    void firstValueFrom(this.http.post<ActionResponse>(`/custodies/${row.id}/reject`, { reason }))
      .then((res) => {
        this.sending.set(false);
        this.reason().done();
        this.toast.success(res.message);
        this.data.reload();
      })
      .catch((err: unknown) => {
        this.sending.set(false);
        const response = err instanceof HttpErrorResponse ? err : null;
        this.actionError.set(response);
        if (response) {
          this.toast.apiError(response.error?.message ?? 'errors.generic', response.error?.code);
        }
      });
  }

  onPage(event: { page: number; per_page: number; sort?: string }): void {
    const current = this.params();
    const sort = event.sort ?? '';
    if (current.page === event.page && current.per_page === event.per_page && current.sort === sort) {
      return;
    }
    this.params.update((p) => ({ ...p, page: event.page, per_page: event.per_page, sort }));
    this.data.reload();
  }
}

function cleanParams(params: object): Record<string, string> {
  const result: Record<string, string> = {};
  for (const [key, value] of Object.entries(params)) {
    if (value !== null && value !== undefined && value !== '' && value !== 'all') {
      result[key] = String(value);
    }
  }
  return result;
}
